(async () => {
  const { env } = await import('node:process');
  const yaml = env.YAML_TEXT;
  if (!yaml) throw new Error('Missing required input YAML_TEXT');
  globalThis.yamlText = yaml;
})();

(async () => {
  const { parseYaml } = await import('@procedures/json');
  const value = parseYaml(globalThis.yamlText);
  globalThis.jsonText = JSON.stringify(value);
})();
